        if (!isset($this->cacheUseNameByShortNameLower[$importKind][strtolower(explode('\\', $tmpRes, 2)[0])]) && !$this->isReservedIdentifier($tmpRes)) {
            $res = $tmpRes;
            $iMin = substr_count($namespaceName, '\\') + 1;
